// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/system/info", wrapper.GetSystemInfo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries", wrapper.ListLibraries)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/libraries", wrapper.CreateLibrary)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/libraries/{libraryId}", wrapper.DeleteLibrary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries/{libraryId}", wrapper.GetLibrary)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/libraries/{libraryId}", wrapper.UpdateLibrary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/folder-roots", wrapper.ListFolderRoots)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/folder-roots/{rootId}/folders", wrapper.ListFolders)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/scan", wrapper.StartLibraryScan)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/items", wrapper.ListLibraryItems)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/facets", wrapper.ListLibraryFacets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/letters", wrapper.ListLibraryLetters)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/folders", wrapper.ListLibraryFolders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/rows", wrapper.ListLibraryRows)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/home/rows", wrapper.GetHomeRows)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/items/{itemId}", wrapper.GetItem)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/items/{itemId}/children", wrapper.ListItemChildren)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/items/{itemId}/identify/search", wrapper.SearchIdentifyCandidates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/items/{itemId}/identify", wrapper.IdentifyItem)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/items/{itemId}/match", wrapper.RemoveItemMatch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/items/{itemId}/refresh", wrapper.RefreshItemMetadata)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/libraries/{libraryId}/refresh", wrapper.RefreshLibraryMetadata)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings/metadata", wrapper.GetMetadataSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings/metadata", wrapper.UpdateMetadataSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/metadata/status", wrapper.GetMetadataStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/playback/sessions", wrapper.CreatePlaybackSession)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/playback/sessions/{sessionId}", wrapper.StopPlaybackSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/playback/sessions/{sessionId}", wrapper.GetPlaybackSession)

	return m
}

